for name,kind in [('PublicClientProtocolObservation','public_client'),('MachineCredentialProtocolObservation','machine_credential')]:
 properties={'resource_kind':{'const':kind},'tenant_id':idtype,'application_id':idtype,'service_principal_id':({'type':'null'} if kind=='public_client' else idtype),'resource_id':idtype,'revision':version,'resource_etag':{'type':'string','pattern':'^"'+('client' if kind=='public_client' else 'cred')+'-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$','description':'Current local resource write precondition, not an HTTP validator for this time-varying observation.'},'local_state':{'enum':['pending','active','revoked']+(['expired'] if kind=='machine_credential' else [])},'profile_state':{'enum':['matching','absent','conflict']},'differences':{'type':'array','maxItems':9,'uniqueItems':True,'items':{'enum':profile_fields}},'observed_at':{'type':'string','format':'date-time'},'authority_checked_at':{'type':'string','format':'date-time'}}
 schemas[name]=obj(properties)
 schemas[name]['allOf']=[{'if':{'properties':{'profile_state':{'const':'conflict'}}},'then':{'properties':{'differences':{'minItems':1}}},'else':{'properties':{'differences':{'maxItems':0}}}}]
parameters={
 'PrincipalMatch':{'in':'header','name':'If-Match','required':True,'description':'Exact principal detail version bound to tenant/principal.','schema':{'type':'string','pattern':'^"sp-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$'}},
 'InvitationMatch':{'in':'header','name':'If-Match','required':True,'description':'Exact current invitation detail revision, bound to tenant and invitation. Missing 428, malformed 400, stale/other resource 412. Acceptance, revocation and reissue invalidate earlier revisions.','schema':{'type':'string','pattern':'^"invite-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$'}},
 'CredentialMatch':{'in':'header','name':'If-Match','required':True,'description':'Exact credential detail API revision, including overlap expiry changes. It is distinct from the private JWT security version.','schema':{'type':'string','pattern':'^"cred-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$'}},
 'ClientMatch':{'in':'header','name':'If-Match','required':True,'description':'Exact managed-client detail ETag bound to tenant/client/version. Missing 428, malformed 400, stale/other resource 412.','schema':{'type':'string','pattern':'^"client-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$'}},
 'TenantID':{'in':'path','name':'tenant','required':True,'description':'Must equal the access token tenant; another tenant returns 404, even if the user also belongs to it.','schema':idtype},
 'Limit':{'in':'query','name':'limit','description':'Bounded keyset page size.','schema':{'type':'integer','minimum':1,'maximum':100,'default':50}},
 'After':{'in':'query','name':'after','description':'Previous next_cursor; ascending UUID keyset, not a snapshot or timestamp ordering guarantee.','schema':idtype},
 'ApplicationMatch':{'in':'header','name':'If-Match','required':True,'description':'Exact application detail ETag, bound to tenant/application/version. Missing: 428; wrong resource or stale: 412.','schema':{'type':'string','pattern':'^"app-[a-f0-9]{32}-[a-f0-9]{32}-[1-9][0-9]*"$'}},
 'ClientAfter':{'in':'query','name':'after','description':'Previous client page next_cursor. Ascending printable client_id, not a UUID or pagination snapshot. URL-encode it.','schema':{'type':'string','minLength':1,'maxLength':128,'pattern':'^[!-~]{1,128}$'}},
 'AuthzMatch':{'in':'header','name':'If-Match','required':True,'description':'Latest tenant/members ETag. Missing: 428; stale: 412.','schema':{'type':'string','pattern':'^"authz-[1-9][0-9]*"$'}},
 'OrgMatch':{'in':'header','name':'If-Match','required':True,'description':'Latest organizations ETag. Missing: 428; stale: 412.','schema':{'type':'string','pattern':'^"org-[1-9][0-9]*"$'}},
}
for name in ['member','org','invitation','session','role','application','client','principal','credential']:parameters[name+'ID']={'in':'path','name':name,'required':True,'schema':idtype}
headers={'RequestID':{'description':'Server-generated request correlation ID.','schema':string},'ETag':{'description':'Quoted resource or collection version for If-Match.','schema':string},'Authenticate':{'description':'Bearer challenge, including invalid_token or insufficient_scope.','schema':string},'RetryAfter':{'description':'Seconds before retrying.','schema':{'type':'integer'}}}
responses={'Problem':{'description':'RFC 9457 problem. Fixed code only; no input, token or SQL echoed. Codes include credential_limit, invalid_credential_state, service_principal_disabled, application_unmanaged, observation_changed, invalid_client_state, invalid_invitation_state, protocol_client_conflict, protected_organization, organization_not_empty, protected_application, application_unavailable, invalid_token, forbidden, insufficient_scope, recent_mfa_required, tenant_mismatch, invalid_request, not_found, already_exists, reserved_role, role_in_use, last_active_owner, root_cannot_move, organization_cycle, version_conflict, precondition_required, invalid_precondition, rate_limited, temporarily_unavailable.','headers':{'X-Request-ID':ref('headers/RequestID'),'WWW-Authenticate':ref('headers/Authenticate'),'Retry-After':ref('headers/RetryAfter')},'content':{'application/problem+json':{'schema':ref('schemas/Problem')}}}}
paths={}
def operation(path,method,opid,summary,out=None,body=None,status=200,owner=False,match=None,paged=False,description=''):
 params=[]
 if '{tenant}' in path:params.append(ref('parameters/TenantID'))
 for name in ['member','org','invitation','session','role','application','client','principal','credential']:
  if '{'+name+'}' in path:params.append(ref('parameters/'+name+'ID'))
 if paged:params += [ref('parameters/Limit'),ref('parameters/'+('ClientAfter' if paged=='client' else 'After'))]
 if match:params.append(ref('parameters/'+match+'Match'))
 success={'description':summary,'headers':{'X-Request-ID':ref('headers/RequestID')}}
 if out:success['content']={'application/json':{'schema':ref('schemas/'+out)}}
 if opid in ['getInvitation','reissueInvitation','createServicePrincipal','getServicePrincipal','disableServicePrincipal','enableServicePrincipal','createMachineCredential','getMachineCredential','revokeMachineCredential','cleanupMachineCredential','createApplication','createManagedClient','getManagedClient','revokeManagedClient','reconcileManagedClient','renameOrganization','deleteOrganization','listOrganizationMembers','getTenant','listMembers','listOrganizations','createOrganization','getMyPermissions','listRoles','listMemberRoles','createRole','getTenantApplication','enableTenantApplication','disableTenantApplication']:success['headers']['ETag']=ref('headers/ETag')
 if opid in ['createTenant','createApplication','createManagedClient','createServicePrincipal','createMachineCredential']:success['headers']['Location']={'description':('Created tenant path; obtain a new tenant-bound authorization before using it.' if opid=='createTenant' else 'Created resource path; read metadata here after a result is known.'),'schema':string}
 op={'operationId':opid,'summary':summary,'description':description or ('Active tenant owner required.' if owner else 'Requires current User, MFA session and tenant-bound grant.'),'tags':['Tenant management' if '{tenant}' in path else 'Identity'],'security':[{'OAuth2':['platform:read' if method=='get' else 'platform:write']}],'parameters':params,'responses':{str(status):success,**{str(code):ref('responses/Problem') for code in [400,401,403,404,409,412,413,415,428,429,503]}}}
 if owner:op['x-authorization']='active_owner'
 if method!='get':op['x-recent-mfa-seconds']=300
 if body:op['requestBody']={'required':True,'content':{'application/json':{'schema':ref('schemas/'+body)}}}
 paths.setdefault(path,{})[method]=op
machine_base='/v1/tenants/{tenant}/applications/{application}/service-principals'
operation('/v1/tenants/{tenant}/applications/{application}/clients/{client}/protocol-status','get','inspectManagedClientProtocol','Observe reviewed protocol fields for an owned public client','PublicClientProtocolObservation',owner=True,description='Active owner/User platform:read only. Current primary authority and resource ownership are checked before and after a fixed private Admin GET; no tenant lock spans the RPC. Local revision changes return 409 observation_changed; lost authority/expiry refuses the response. Bounded four-second total context and three-second Admin timeout, no redirects or caller destination. matching means only the nine reviewed non-secret fields agree, not login readiness or a complete engine health proof. absent/conflict do not create, activate, revoke, delete or adopt anything. Pending stays pending. Only controlled difference field names, local revision/state, namespace and distinct observation/authority-check times and resource_etag (the local resource write precondition, not an observation HTTP validator) are returned; no actual differing values, Admin body, secret/hash/registration token. No GET body/query, audit/outbox/authority mutation or automatic retry; dependency failure 503. Existing explicit reconcile/revoke retain MFA/ETag requirements.')
operation('/v1/tenants/{tenant}/applications/{application}/service-principals/{principal}/credentials/{credential}/protocol-status','get','inspectMachineCredentialProtocol','Observe reviewed protocol fields for an owned machine credential','MachineCredentialProtocolObservation',owner=True,description='Active owner/User platform:read only, including disabled app/SP and revoked/expired credential metadata. Private GET only, primary authority/resource rechecked afterward; RPC does not hold a tenant lock. Revision/profile changes return 409 observation_changed. Matching covers reviewed non-secret fields, never verifies or recovers SK or proves JWT/consumer readiness. Pending/unknown/lost SK cannot be activated or recovered here; revoke/cleanup/recreate remains explicit. Absent remote registration does not itself change local active state or revoke an issued JWT: use local revoke for authority changes. Returns only fixed namespace/revision/state/time and enumerated difference names; no AK/secret/hash/Admin values. Bounded deadlines, no request body/query, protocol/local writes, audit/outbox mutation, caller destination or automatic repair. Dependency failure 503; same User/tenant/owner bounds as credential metadata.')
operation(machine_base,'get','listServicePrincipals','List this owned application machine principals','ServicePrincipalPage',owner=True,paged=True)
operation(machine_base,'post','createServicePrincipal','Create a tenant-owned machine identity','ServicePrincipal','ServicePrincipalInput',201,True,description='Active owner/recent MFA; app must be owned/enabled/available. Maximum 100 principals per app. SP belongs to the tenant owner collective, not the creator personal session. No machine key or User grant is created; current User authorization stays valid.')
operation(machine_base+'/{principal}','get','getServicePrincipal','Read one machine principal and version','ServicePrincipal',owner=True)
for action in ['disable','enable']:
 operation(machine_base+'/{principal}/'+action,'post',action+'ServicePrincipal',action.title()+' a machine principal','ServicePrincipal','Empty',owner=True,match='Principal',description='Active owner/recent MFA and exact principal ETag. Changes principal security version and User audit/outbox, retaining credentials. Old JWTs fail immediately at the reference resource and never revive after restoration. Restored valid credentials may obtain fresh tokens. Same-state/current ETag no-op; enabling requires app available/enabled. Does not change the User tenant authorization version.')
machine_keys=machine_base+'/{principal}/credentials'
operation(machine_keys,'get','listMachineCredentials','List credential metadata without SK','MachineCredentialPage',owner=True,paged=True)
operation(machine_keys,'post','createMachineCredential','Issue an independent one-time AK/SK credential','MachineCredentialCreated','MachineCredentialInput',201,True,description='Active owner/recent MFA and enabled owned app/principal. TTL 1–90 days, maximum two live active/pending credentials and 100 lifetime records per principal. Fixed client_credentials-only, machine:invoke and this app URN audience; no platform management/refresh/ID token. Commits pending, registers and verifies exact private engine profile, then rechecks User authority and principal/application versions before activation. SK returned only here and never stored recoverably in business DB. Unknown response/commit: GET/list, revoke and create a new credential; pending cannot be reconciled active or have SK recovered. On successful activation only, other active key expiry is shortened to at most 24h overlap; API revision changes, security version remains, so cached old JWT stays usable during overlap. Failed creation preserves prior key expiry. No automatic request replay.')
paths[machine_keys]['post']['x-playground-execute']=False
paths[machine_keys]['post']['x-playground-reason']='Use the dedicated credential page to save the one-time SK. Generic Playground redacts secrets and therefore cannot deliver it safely.'
operation(machine_keys+'/{credential}','get','getMachineCredential','Read credential metadata and API revision','MachineCredential',owner=True,description='Active owner only. No secret/hash/recoverable private key in this response. Expired is derived from primary time. API revision may differ from internal JWT security version because overlap expiry metadata changes do not revive or invalidate a still-valid token.')
operation(machine_keys+'/{credential}/revoke','post','revokeMachineCredential','Irreversibly revoke a machine credential','MachineCredential','Empty',owner=True,match='Credential',description='Active owner/recent MFA. Pending/active/expired becomes revoked with higher API/security versions and transactional User audit/outbox; same-state/current revision no-op. Key and all old machine JWTs are refused by primary authority immediately. Other keys, SPs and User login remain valid; no shared SID logout. Revoke still works when SP/app is disabled.')
operation(machine_keys+'/{credential}/cleanup','post','cleanupMachineCredential','Clean up a matching revoked credential protocol object','MachineCredential','Empty',owner=True,match='Credential',description='Active owner/recent MFA. Only revoked credentials; never activates pending or reveals/recreates SK. Fixed private Admin profile/ownership check; foreign/drifted objects not deleted. Local revoked tombstone persists even when remote cleanup fails. Absence is observed, not a permanent assurance about old timed-out transactions. Works with disabled SP/app.')
operation('/v1/tenants/{tenant}/machine-events','get','listMachineEvents','Read controlled machine issuance audit metadata','MachineEventPage',paged=True,description='Requires audit.read on token tenant, explicit deny first. Machine actor is SP/credential, not its human creator. ID/application/SP/credential/action/time only, no token/SK/payload. UUID ascending keyset, no snapshot/immutable archive guarantee. Separate transactional machine outbox; periodic consumers not yet implemented.')
operation('/v1/tenants/{tenant}/applications','post','createApplication','Create a tenant-owned application','Application','ApplicationInput',201,True,description='Active owner and recent MFA required. Creates application, this tenant association, immutable ownership and audit/outbox atomically. Maximum 20 owned apps per tenant. Other tenants and built-in/shared applications are not made owned by this call. No OAuth client or secret is issued; no unrelated tenant authorization version change.')
operation('/v1/tenants/{tenant}/applications/{application}/clients','post','createManagedClient','Register a pending public PKCE client','ManagedClient','ManagedClientInput',201,True,description='Active owner/recent MFA; only applications owned by this tenant and currently available/enabled. Maximum 100 lifetime registrations per app, including revoked tombstones. Server chooses a random client_id. Starts pending and inactive, requiring separate reconcile to register and verify the engine. Fixed authorization_code/refresh_token, S256 PKCE, no client secret, fixed scopes openid offline_access platform:read and platform audience. No custom scopes/audience/grants/authentication/JWKS fields. Response loss: read application clients before creating another registration.')
operation('/v1/tenants/{tenant}/applications/{application}/clients/{client}','get','getManagedClient','Read this tenant owned managed-client state and version','ManagedClient',owner=True,description='Active owner only. Database metadata without a protocol Admin fetch or secrets. client path is a server-generated 32-hex ID; existing shared/external registrations remain metadata-only via the application client list. Root application path and client must belong to this tenant ownership record.')
operation('/v1/tenants/{tenant}/applications/{application}/clients/{client}/revoke','post','revokeManagedClient','Irreversibly revoke a managed client in the authority database','ManagedClient','Empty',owner=True,match='Client',description='Active owner and recent MFA. First commits inactive and a higher client version with audit/outbox, invalidating this client grants immediately. No engine call or shared SID logout; other clients and central SSO remain valid. Pending or active can be revoked, never restored. Same-state/current ETag no-op. Separate reconcile can clean up an owned engine object; failed protocol cleanup never restores authority.')
operation('/v1/tenants/{tenant}/applications/{application}/clients/{client}/reconcile','post','reconcileManagedClient','Reconcile the exact owned protocol client profile','ClientReconciliation','Empty',owner=True,match='Client',description='Active owner and recent MFA, exact ETag, total four-second authority transaction bound. Pending: read the fixed Admin destination, create if absent, read back and verify exact profile and ownership before activation/version/audit commit. Active: verify profile without changing authority. Revoked: delete only a matching owned engine object, retaining the revoked tombstone and auditing the cleanup check. Foreign/drifted profile is 409 protocol_client_conflict and never overwritten/deleted/adopted. Global/local app disable blocks activation, not revocation/cleanup. Unknown transport/commit outcome is not auto-replayed: reread state and choose a fresh reconciliation. Local pending/revoked clients cannot issue usable business tokens, including remote orphans. Absence is observed, not permanent physical-deletion assurance.')
operation('/v1/tenants/{tenant}/applications','get','listTenantApplications','List applications explicitly associated with this space','ApplicationPage',owner=True,paged=True,description='Active owner only. Includes disabled associations for recovery; no global application discovery, implicit enablement or secret access. The managed flag identifies this tenant ownership; separate owner-only creation handles owned apps.')
operation('/v1/tenants/{tenant}/applications/{application}','get','getTenantApplication','Read an application association and resource-bound version','Application',owner=True,description='Active owner only. ETag binds tenant ID, application ID and association version. Global availability and per-tenant enablement are separate. Only existing associations may be managed.')
operation('/v1/tenants/{tenant}/applications/{application}/clients','get','listApplicationClients','Read registered client metadata for an associated application','ApplicationClientPage',owner=True,paged='client',description='Active owner only, including disabled associations. Exact registered client_id, redirect URI, scopes, audience, active flag and version; never client secrets, cookies or token material. Cursor is printable client_id (not UUID), sorted ascending within this application. This GET does not change protocol configuration. managed/state distinguish tenant-owned lifecycle rows from external built-in registrations; no secret/authentication credential is returned.')
for action in ['enable','disable']:
 operation('/v1/tenants/{tenant}/applications/{application}/'+action,'post',action+'TenantApplication',action.title()+' an existing application association','Application','Empty',owner=True,match='Application',description='Active owner and recent MFA required. Exact tenant/application/version ETag. Atomically changes only this association version, records audit/outbox; disabling revokes this tenant/application grants and BFF sessions. Other spaces, applications and central SSO remain valid; no shared Hydra SID logout. Re-enabling requires new authorization and never resurrects old grants. Same-state requests with current ETag are no-ops. Management platform disable is 409 protected_application; globally suspended application enable is 409 application_unavailable. No registration or global registry mutation.')
operation('/v1/me','get','getMe','Get the verified current principal','Me')
operation('/v1/tenants','get','listMyTenants','List active spaces of the current user','TenantPage',paged=True)
operation('/v1/tenants','post','createTenant','Create a space and initial owner atomically','TenantCreated','TenantInput',201,description='Recent MFA required. Maximum 20 active owned spaces. The first-party platform is enabled in the new space; unrelated applications are not enabled. Duplicate slug is 409; no automatic retry or idempotency-key guarantee.')
operation('/v1/tenants/{tenant}','get','getTenant','Get the token-bound space and versions','Tenant')
operation('/v1/tenants/{tenant}/members','get','listMembers','List space memberships','MemberPage',owner=True,paged=True)
for action in ['suspend','restore']:operation('/v1/tenants/{tenant}/members/{member}/'+action,'post',action+'Member',action.title()+' a membership',body='Empty',status=204,owner=True,match='Authz',description='Owner and recent MFA required. Last active owner cannot be suspended. Changes increment membership and tenant versions, invalidating existing tenant grants; restoration never revives old grants.')
operation('/v1/tenants/{tenant}/organizations','get','listOrganizations','List space organization nodes','OrganizationPage',owner=True,paged=True)
operation('/v1/tenants/{tenant}/organizations','post','createOrganization','Create an organization under an existing parent','OrganizationCreated','OrganizationInput',201,True,'Org')
operation('/v1/tenants/{tenant}/organizations/{org}/rename','post','renameOrganization','Rename a non-root organization','OrganizationCreated','OrganizationRename',owner=True,match='Org',description='Recent MFA required. Nonblank trimmed name, at most 128 UTF-8 bytes. Increments only org_version: names do not confer authority. Identical normalized name with current ETag is a no-op. Root is 409 protected_organization; changing the space name is outside organization delegation.')
operation('/v1/tenants/{tenant}/organizations/{org}','delete','deleteOrganization','Delete an empty non-root organization','OrganizationCreated','Empty',owner=True,match='Org',description='Recent MFA required. No cascade. Root is 409 protected_organization. Any direct child or direct member association, including suspended/left members, is 409 organization_not_empty. Tenant lock serializes with create/move/assign. Removes closure references, increments org_version and tenant authz_version with audit/outbox atomically; old tenant grants must reauthorize. Missing/already deleted returns 404. Network result unknown: read before deciding to retry.')
operation('/v1/tenants/{tenant}/organizations/{org}/members','get','listOrganizationMembers','List direct organization member associations','MemberPage',owner=True,paged=True,description='Requires BOTH organizations.read and members.read, explicit deny wins. Includes inactive memberships so stale associations can be removed. Direct associations only, not descendants or effective permissions. Verified email has the same members.read protection as the space member directory. Returns authz ETag for removal. UUID keyset pagination, no snapshot.')
operation('/v1/tenants/{tenant}/organizations/{org}/members/{member}','delete','unassignOrganization','Remove one direct organization member association',body='Empty',status=204,owner=True,match='Authz',description='Recent MFA and organizations.write required. Both objects must belong to this tenant. Inactive members can be unassigned. Leaves membership status, owner/role bindings and other organization associations intact. A real removal increments tenant authz_version and records audit/outbox; old tenant grants must reauthorize. Already absent association with current ETag is a no-op; missing/foreign objects return 404. Organization assignment does not itself grant access.')
operation('/v1/tenants/{tenant}/organizations/{org}/move','post','moveOrganization','Preview or execute an organization move','MoveResult','MoveInput',owner=True,match='Org',description='Owner and recent MFA required, including preview. Root/cycle/depth checks apply. Preview changes no state. Executing changes organization and tenant authorization versions; obtain a new authorization afterwards.')
operation('/v1/tenants/{tenant}/organizations/{org}/members/{member}','put','assignOrganization','Associate a membership with an organization',body='Empty',status=204,owner=True,match='Authz',description='Association does not grant owner or other roles. Changes tenant authorization version; obtain a new authorization afterwards.')
operation('/v1/tenants/{tenant}/invitations','get','listInvitations','List invitation metadata without bearer secrets','InvitationPage',owner=True,paged=True)
operation('/v1/tenants/{tenant}/invitations','post','createInvitation','Create an email-bound one-time invitation','InvitationCreated','InvitationInput',201,True,description='Owner and recent MFA required. Token is returned once, stored only as a digest and never in audit/outbox. The caller delivers it securely; no external email is sent. Invitations grant membership only.')
operation('/v1/tenants/{tenant}/invitations/{invitation}/revoke','post','revokeInvitation','Close an invitation so its proof cannot be accepted',body='Empty',status=204,owner=True,description='Owner and recent MFA required. Idempotently closes the proof; already closed proofs stay closed. Audit records the first revocation; closed includes accepted or revoked.')
operation('/v1/tenants/{tenant}/invitations/{invitation}','get','getInvitation','Read current invitation metadata and revision','InvitationDetail',description='User platform:read and current invitations.manage. Tenant-bound primary read; response contains email/state/expiry/revision only, never proof/digest or arbitrary payload. Missing legacy revision metadata is revision 1 without modifying the invitation. ETag binds tenant/invitation/revision. GET has no request body. Closed covers accepted/revoked; closed invitations cannot reopen.')
operation('/v1/tenants/{tenant}/invitations/{invitation}/reissue','post','reissueInvitation','Replace a lost or expired invitation proof once','InvitationReissued','Empty',match='Invitation',description='User platform:write, current invitations.manage and recent MFA. Empty JSON body; exact resource ETag. Only pending/expired invitations; closed returns 409 invalid_invitation_state with a current revision. Replaces proof digest and expiry for 24 hours, leaves tenant/resource/target email fixed, and makes the current manager responsible for subsequent acceptance. Revision and controlled audit/outbox commit atomically; no tenant authorization version change. Concurrent same-revision updates allow one success, other 412. Acceptance/revocation also increase revision and serialize with updates; old proof cannot join afterward. Secret returned once, never recoverable or automatically replayed. On uncertain result read metadata and explicitly update again if necessary. No invitation email is sent. Generic Playground redacts proof; use the dedicated invitation dialog for secure handoff.')
operation('/v1/invitations/accept','post','acceptInvitation','Consume an invitation for the verified user','MembershipCreated','InvitationProof',201,description='Recent MFA required. The proof selects the destination tenant. Verified email must match; membership only, no implicit role. Consumed/expired/revoked proofs are invalid. Acceptance increments destination tenant authorization version.')
operation('/v1/tenants/{tenant}/audit-exports','get','exportAuditBatch','Read one bounded audit export batch','AuditBatch',paged=True,description='User platform:read and current audit.read, including delegated auditors. Kind management (default) or machine; 1–100 rows, default 50. Reads current primary authority and data in one transaction; no recent-MFA requirement beyond the valid User grant/session. Cursor must exist in this tenant and kind; unknown/foreign/cross-kind cursor is 404. Frozen sso.audit.batch.v1 projection: IDs, controlled action/time and optional role-binding snapshot; no raw request, email, token/proof/secret or creator-as-machine-actor. Empty items is [], next_cursor is null or the last included ID when more rows exist. No query/body tenant override or request body. No mutation/audit of the GET itself. Individual batches describe their own primary read time/authorization version; multiple batches are not a frozen global snapshot or signed archival proof. Browser downloads reread authority instead of saving a stale preview.')
paths['/v1/tenants/{tenant}/audit-exports']['get']['parameters'].append({'in':'query','name':'kind','description':'Separate management or machine audit source; cursor cannot cross kinds.','schema':{'enum':['management','machine'],'default':'management'}})
operation('/v1/tenants/{tenant}/audit-events','get','listAuditEvents','List controlled space audit metadata','AuditEventPage',owner=True,paged=True)
operation('/v1/sessions','get','listMySessions','List central sessions of the current user','SessionPage',paged=True)
operation('/v1/sessions/{session}/revoke','post','revokeMySession','Revoke one central session owned by the current user',body='Empty',status=204,description='Recent MFA required. Revokes business authority before queued Hydra cleanup. Revoking the current session invalidates this access token. Session cookie digests, CSRF values, factor secrets and tokens are never returned.')
operation('/v1/me/security-events','get','listMySecurityEvents','List own security events newest first','SecurityEventPage',paged=True,description='Current User only, across spaces; platform:read and a valid current tenant grant required, no tenant audit permission. Returns only reviewed event ID, action and timestamp; excludes internal targets, email, password, MFA proofs, IP and payloads. Order: occurred_at DESC, id DESC. after is the last event ID from this same user; unknown, hidden or another user cursor returns 404. Same-timestamp events use descending ID as a stable tie-breaker. No pagination snapshot, immutable-archive or complete security-monitoring guarantee. Reset-request events record receipt of a request, not proof that the user initiated it.')
operation('/v1/me/security','get','getMySecurity','Read own MFA/recovery/session metadata','SecuritySummary',description='Current verified user only, across their spaces. Counts and authentication metadata only; no factor secret, code digest, cookie or recovery code. Requires an active current tenant grant. Recovery-code regeneration is a separate trusted-origin password+TOTP interaction, never a Bearer API.')
operation('/v1/sessions/revoke-others','post','revokeOtherSessions','Revoke other central sessions, retaining the current session','SessionsRevoked','Empty',description='Recent MFA required. No user ID input: only current user sessions, across their spaces and applications. Revokes other committed session records and their BFF/grant authority, queuing protocol cleanup in the same transaction. Current session/grants remain valid; authentication completing later may create a new session. No-op returns zero. Does not invalidate the current grant or update auth_time.')
operation('/v1/tenants/{tenant}/permissions','get','getMyPermissions','Get the current membership effective permissions','PermissionSnapshot',description='Any current member may inspect their own effective set. Explicit deny wins across tenant-scoped roles. Reserved owner roles.manage is retained for recovery and cannot be expressed in custom policies.')
operation('/v1/tenants/{tenant}/roles','get','listRoles','List tenant roles and rules','RolePage',owner=True,paged=True)
operation('/v1/tenants/{tenant}/roles','post','createRole','Create a tenant-scoped custom role','RoleCreated','RoleInput',201,True,'Authz')
operation('/v1/tenants/{tenant}/roles/{role}','put','replaceRole','Replace all custom role rules',body='RoleUpdate',status=204,owner=True,match='Authz',description='Owner and recent MFA required. Reserved owner is immutable. Duplicate rules and reserved permissions are invalid. Changed policies increment tenant authorization version and invalidate prior tenant grants; identical rules are a no-op.')
operation('/v1/tenants/{tenant}/roles/{role}','delete','deleteRole','Delete an unbound custom role',body='Empty',status=204,owner=True,match='Authz',description='Owner and recent MFA required. Built-in owner cannot be deleted; roles with bindings return role_in_use. Changed state invalidates tenant grants.')
operation('/v1/tenants/{tenant}/members/{member}/roles','get','listMemberRoles','List one tenant membership role bindings','MemberRoles',owner=True)
for method,action in [('put','bind'),('delete','unbind')]:
 operation('/v1/tenants/{tenant}/members/{member}/roles/{role}',method,action+'Role',action.title()+' a tenant role to a membership',body='Empty',status=204,owner=True,match='Authz',description='Owner and recent MFA required. Both objects must belong to the token tenant. Owner grants/revocations are explicit reserved-role operations; last active owner cannot be removed. Repeating the same binding state with the current ETag is a no-op. A real change increments tenant authz_version; old grants must reauthorize. Audit preserves member and role metadata even after role deletion.')
operation_permissions={'getInvitation':'invitations.manage','reissueInvitation':'invitations.manage','exportAuditBatch':'audit.read','listMachineEvents':'audit.read','renameOrganization':'organizations.write','deleteOrganization':'organizations.write','unassignOrganization':'organizations.write','listOrganizationMembers':'organizations.read+members.read','listMembers':'members.read','suspendMember':'members.write','restoreMember':'members.write','listOrganizations':'organizations.read','createOrganization':'organizations.write','moveOrganization':'organizations.write','assignOrganization':'organizations.write','listInvitations':'invitations.manage','createInvitation':'invitations.manage','revokeInvitation':'invitations.manage','listAuditEvents':'audit.read'}
for operations in paths.values():
 for op in operations.values():
  permission=operation_permissions.get(op['operationId'])
  if permission:
   op['x-authorization']='permission:'+permission
   op['description']=('Requires '+permission+' on the token tenant. Explicit deny overrides other allows, including owner operational privileges. ')+op['description'].replace('Active tenant owner required.','').replace('Owner and recent MFA required.','Recent MFA required.').replace('Owner and recent MFA required, including preview.','Recent MFA required, including preview.')
  elif op.get('x-authorization')=='active_owner':op['x-authorization']='reserved_owner:roles.manage'
